import{_ as e,o as n,c as l,a4 as d}from"./chunks/framework.BWWfBZka.js";const x=JSON.parse('{"title":"67 道高频现场面试真题与深层考点 (Interview Prep)","description":"","frontmatter":{},"headers":[],"relativePath":"11_Interview_Prep.md","filePath":"11_Interview_Prep.md","lastUpdated":1788996924000}'),s={name:"11_Interview_Prep.md"};function r(o,t,a,i,g,c){return n(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="_67-道高频现场面试真题与深层考点-interview-prep" tabindex="-1">67 道高频现场面试真题与深层考点 (Interview Prep) <a class="header-anchor" href="#_67-道高频现场面试真题与深层考点-interview-prep" aria-label="Permalink to &quot;67 道高频现场面试真题与深层考点 (Interview Prep)&quot;">​</a></h1><blockquote><p><em>考官在白板前真正提问的经典高频考题，揭示每一个问题背后考官真正考核的核心意图与得分点。</em></p></blockquote><hr><p><strong>题目总数</strong>: 67</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">考核类别</th><th style="text-align:left;">现场面试原题 (Question)</th><th style="text-align:left;">考官深层考察意图与关键采分点 (What they are testing)</th><th style="text-align:center;">难度</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>Design [X]. You have 45 minutes.</strong></td><td style="text-align:left;">Structure above all: requirements, estimation, high level, deep dive, wrap up. Running out of time is the top failure.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>What are the functional requirements?</strong></td><td style="text-align:left;">You should ask this in the first two minutes, unprompted.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>What scale are we designing for?</strong></td><td style="text-align:left;">Users, QPS, data volume. Every decision downstream depends on the answer.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>Estimate the storage this needs per year.</strong></td><td style="text-align:left;">Back-of-the-envelope maths with stated assumptions. Being roughly right is enough.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>Why did you choose that database?</strong></td><td style="text-align:left;">Every component invites this. An unjustified choice is a lost point.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>What is the bottleneck in your design?</strong></td><td style="text-align:left;">Self-awareness. Usually the database. Say so before they do.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>What happens when this component fails?</strong></td><td style="text-align:left;">Every box you draw should have a failure story.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Process</strong></td><td style="text-align:left;"><strong>How would you know if this system was broken right now?</strong></td><td style="text-align:left;">Observability. Most candidates never mention monitoring at all.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Explain CAP theorem, then tell me where your design sits.</strong></td><td style="text-align:left;">Applying theory rather than reciting it.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Strong or eventual consistency here? Justify it.</strong></td><td style="text-align:left;">Product judgement, not just technical preference.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>What is the difference between latency and throughput?</strong></td><td style="text-align:left;">Basic but frequently muddled under pressure.</td><td style="text-align:center;"><code>Foundation</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>How do you scale this from 1,000 to 10 million users?</strong></td><td style="text-align:left;">The staged scaling narrative: cache, replicas, shards, services.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Fundamentals</strong></td><td style="text-align:left;"><strong>Why not just use a bigger server?</strong></td><td style="text-align:left;">Vertical scaling limits and cost curves. Sometimes the answer is yes.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>SQL or NoSQL for this? Defend your choice.</strong></td><td style="text-align:left;">Judgement. Defaulting to NoSQL for scale without reasoning is a red flag.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>How would you shard this data? What is your partition key?</strong></td><td style="text-align:left;">The most consequential decision in the design.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Your partition key is user ID. What about the top 1% of users?</strong></td><td style="text-align:left;">Hot partitions. The follow-up that catches most candidates.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>How do you add a shard without moving all the data?</strong></td><td style="text-align:left;">Consistent hashing.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>A user updates their profile and sees the old version. Why?</strong></td><td style="text-align:left;">Replication lag and read-your-writes consistency.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>How do you handle a schema change on a live 500 million row table?</strong></td><td style="text-align:left;">Expand-contract migration. A real operational question.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Databases</strong></td><td style="text-align:left;"><strong>Two users buy the last item simultaneously. Walk me through it.</strong></td><td style="text-align:left;">Transactions, locking, optimistic concurrency.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>Where would you add caching in this design?</strong></td><td style="text-align:left;">Multiple layers: browser, CDN, application, database.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>How do you invalidate the cache?</strong></td><td style="text-align:left;">The genuinely hard problem. TTL, write-through, event-driven invalidation.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>A hot key expires and the database falls over. Prevent it.</strong></td><td style="text-align:left;">Cache stampede: locking, probabilistic early refresh, staggered TTLs.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Caching</strong></td><td style="text-align:left;"><strong>What is your cache hit rate, and what happens if it drops?</strong></td><td style="text-align:left;">Whether you thought about the cache-miss path capacity.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Scaling</strong></td><td style="text-align:left;"><strong>The load balancer is a single point of failure. Fix it.</strong></td><td style="text-align:left;">Redundant balancers, DNS failover, anycast.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Scaling</strong></td><td style="text-align:left;"><strong>How does a new server start receiving traffic?</strong></td><td style="text-align:left;">Service discovery, health checks, registration.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Scaling</strong></td><td style="text-align:left;"><strong>Traffic is 10x forecast. What breaks first?</strong></td><td style="text-align:left;">Reasoning about your own design&#39;s weakest link.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Scaling</strong></td><td style="text-align:left;"><strong>What do you turn off first under extreme load?</strong></td><td style="text-align:left;">Graceful degradation and load shedding. Rarely mentioned unprompted.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>Why put a queue here rather than calling directly?</strong></td><td style="text-align:left;">Decoupling, buffering, retry. And when a direct call is correct.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>How do you guarantee a message is processed exactly once?</strong></td><td style="text-align:left;">Honestly: at-least-once delivery plus idempotent consumers.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>The consumer crashes mid-batch. What happens?</strong></td><td style="text-align:left;">Offset commit strategy and duplicate handling.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>A message fails repeatedly. Where does it go?</strong></td><td style="text-align:left;">Dead letter queues, retry limits, alerting.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Messaging</strong></td><td style="text-align:left;"><strong>How do you preserve ordering while processing in parallel?</strong></td><td style="text-align:left;">Partition by key. Ordering within a partition, not globally.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>The downstream service is slow. What does the user see?</strong></td><td style="text-align:left;">Timeouts, circuit breakers, fallbacks. Not an infinite spinner.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>How do you prevent one slow dependency from taking down your service?</strong></td><td style="text-align:left;">Bulkheads, timeouts, circuit breakers, thread pool isolation.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>Design a rate limiter for this API.</strong></td><td style="text-align:left;">A standalone question in its own right. Know token bucket cold.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>An entire region goes down. What is your plan?</strong></td><td style="text-align:left;">Multi-region, RTO and RPO, failover mechanics, data replication.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Reliability</strong></td><td style="text-align:left;"><strong>How do you know your failover actually works?</strong></td><td style="text-align:left;">Chaos engineering and game days. Untested failover does not work.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Real-time</strong></td><td style="text-align:left;"><strong>How does the client learn about a new message?</strong></td><td style="text-align:left;">Polling, long polling, SSE or WebSockets, with the trade-offs.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Real-time</strong></td><td style="text-align:left;"><strong>You have 10 million persistent connections. How do you manage them?</strong></td><td style="text-align:left;">Connection servers, service discovery, horizontal scaling of the WS layer.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Real-time</strong></td><td style="text-align:left;"><strong>The user is offline when the message arrives. Now what?</strong></td><td style="text-align:left;">Message store, push notifications, delivery on reconnect.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>How is a request authenticated across your services?</strong></td><td style="text-align:left;">Gateway validation, token propagation, service-to-service auth.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">43</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Where does the token get validated, and by whom?</strong></td><td style="text-align:left;">Gateway versus each service, and the trade-off between them.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">44</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>Someone floods your API with requests. Respond.</strong></td><td style="text-align:left;">Rate limiting, WAF, DDoS protection, cost controls.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">45</td><td style="text-align:left;"><strong>Security</strong></td><td style="text-align:left;"><strong>This data is subject to GDPR. What changes in your design?</strong></td><td style="text-align:left;">Data residency, deletion, encryption, audit. Architecture is affected.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">46</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>How would you debug a slow request across eight services?</strong></td><td style="text-align:left;">Distributed tracing and correlation IDs.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">47</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>What is your SLO for this system?</strong></td><td style="text-align:left;">Turning reliability into a number with consequences.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">48</td><td style="text-align:left;"><strong>Observability</strong></td><td style="text-align:left;"><strong>What do you alert on, and what do you deliberately not alert on?</strong></td><td style="text-align:left;">Alerting on symptoms rather than causes; avoiding alert fatigue.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">49</td><td style="text-align:left;"><strong>Cost</strong></td><td style="text-align:left;"><strong>What does this system cost to run per month?</strong></td><td style="text-align:left;">Commercial awareness. Very few candidates can even estimate.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">50</td><td style="text-align:left;"><strong>Cost</strong></td><td style="text-align:left;"><strong>Your storage bill doubled. Investigate.</strong></td><td style="text-align:left;">Retention, tiering, replication factor, unbounded log growth.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">51</td><td style="text-align:left;"><strong>Cost</strong></td><td style="text-align:left;"><strong>How would you reduce this cost by half without hurting users?</strong></td><td style="text-align:left;">Caching, tiering, compression, right-sizing, reserved capacity.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">52</td><td style="text-align:left;"><strong>Trade-offs</strong></td><td style="text-align:left;"><strong>Should this be microservices or a monolith?</strong></td><td style="text-align:left;">Usually a monolith for a small team. Saying so scores points.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">53</td><td style="text-align:left;"><strong>Trade-offs</strong></td><td style="text-align:left;"><strong>Why not use Kafka here?</strong></td><td style="text-align:left;">Recognising when a simpler queue or a direct call is correct.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">54</td><td style="text-align:left;"><strong>Trade-offs</strong></td><td style="text-align:left;"><strong>What would you do differently with 10x the budget? With half?</strong></td><td style="text-align:left;">Whether your design is a considered choice or the only one you know.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">55</td><td style="text-align:left;"><strong>Trade-offs</strong></td><td style="text-align:left;"><strong>What is the simplest thing that would work?</strong></td><td style="text-align:left;">Judgement. Over-engineering is as much a failure as under-engineering.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">56</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design a parking lot system.</strong></td><td style="text-align:left;">The most asked LLD question, especially at Indian companies.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">57</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design an elevator system.</strong></td><td style="text-align:left;">State machines and scheduling in object form.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">58</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design BookMyShow or a movie ticket booking system.</strong></td><td style="text-align:left;">Concurrency and seat locking at the class level.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">59</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design Splitwise.</strong></td><td style="text-align:left;">Data modelling for balances and settlement.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">60</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design a vending machine.</strong></td><td style="text-align:left;">The classic state pattern question.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">61</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Design a notification system with multiple channels.</strong></td><td style="text-align:left;">Strategy and factory patterns applied cleanly.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">62</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Which SOLID principle does this design violate?</strong></td><td style="text-align:left;">The standard framing for LLD feedback.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">63</td><td style="text-align:left;"><strong>Low Level Design</strong></td><td style="text-align:left;"><strong>Is this design thread-safe? Make it so.</strong></td><td style="text-align:left;">Concurrency at the object level.</td><td style="text-align:center;"><code>Advanced</code></td></tr><tr><td style="text-align:center;">64</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Walk me through the architecture of a system you have built.</strong></td><td style="text-align:left;">Your own work, which is where senior interviews actually go.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">65</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>What is the hardest technical decision you have made?</strong></td><td style="text-align:left;">Judgement and ownership. Prepare a real story with a trade-off.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">66</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>What would you change about a system you worked on?</strong></td><td style="text-align:left;">Self-awareness and design maturity.</td><td style="text-align:center;"><code>Core</code></td></tr><tr><td style="text-align:center;">67</td><td style="text-align:left;"><strong>Practice</strong></td><td style="text-align:left;"><strong>Explain this architecture to a non-technical stakeholder.</strong></td><td style="text-align:left;">Communication, which decides senior hiring more than depth does.</td><td style="text-align:center;"><code>Core</code></td></tr></tbody></table>',5)])])}const f=e(s,[["render",r]]);export{x as __pageData,f as default};
